async (page) => {
  await page.addInitScript(() => {
    const W = window.WebSocket; window.__rx = []; window.__tx = []; window.__wsurls = [];
    window.WebSocket = new Proxy(W, { construct(t, a) { const s = new t(...a); window.__wsurls.push(a[0]);
      s.addEventListener('message', e => { if (typeof e.data === 'string' && window.__rx.length < 200000) window.__rx.push(e.data); });
      const send = s.send.bind(s); s.send = d => { window.__tx.push(String(d).slice(0,200)); return send(d); };
      return s; } });
  });
  await page.reload();
  await page.waitForTimeout(6000);
  return await page.evaluate(() => {
    const rx = window.__rx; const kinds = {};
    for (const m of rx) { const k = m.split('^')[0].slice(0,20); kinds[k] = (kinds[k]||0)+1; }
    return { urls: window.__wsurls, total: rx.length, kinds, tx: window.__tx.slice(0,15), sample: rx.slice(0,5).map(s=>s.slice(0,200)), vu: rx.filter(m=>m.includes('VU')).slice(-2).map(s=>s.slice(0,300)) };
  });
}

