async (page) => {
  await page.waitForTimeout(20000);
  const out = await page.evaluate(() => {
    const state = {};
    const vus = [];
    for (const m of window.__rx) {
      for (const line of m.replace(/^3:::/, '').split('\n')) {
        const p = line.split('^');
        if ((p[0]==='SETD'||p[0]==='SETS') && p.length>=3) state[p[1]] = p.slice(2).join('^');
        if (p[0]==='VU2') { const b = Uint8Array.from(atob(p[1]), c=>c.charCodeAt(0)); vus.push(Array.from(b)); }
      }
    }
    return { state, vus };
  });
  const fs = require('fs');
  fs.writeFileSync('.playwright-mcp/baseline-state.json', JSON.stringify(out.state, null, 0));
  const hdr = out.vus[0].slice(0,8);
  const n = hdr[0], per = 6, off = 8;
  const st = out.state;
  const rows = [];
  for (let c=0;c<n;c++){ const pre=[],post=[],pf=[],comp=[];
    for (const v of out.vus){ const o=off+c*per; pre.push(v[o]);post.push(v[o+1]);pf.push(v[o+2]);comp.push(v[o+5]); }
    const avg=a=>Math.round(a.reduce((x,y)=>x+y,0)/a.length), max=a=>Math.max(...a);
    rows.push({ch:c+1,name:st[`i.${c}.name`],mix:st[`i.${c}.mix`],mute:st[`i.${c}.mute`],gain:st[`i.${c}.gain`]??st[`hw.${c}.gain`],pan:st[`i.${c}.pan`],preAvg:avg(pre),preMax:max(pre),postAvg:avg(post),pfAvg:avg(pf),pfMax:max(pf),compLast:comp[comp.length-1]});
  }
  const keys = Object.keys(st);
  return { hdr, frames: out.vus.length, len: out.vus[0].length, keyCount: keys.length, rows, master: {mix: st['m.mix'], dim: st['m.dim'], mute: st['m.mute']}, varKeys: keys.filter(k=>/^var\.|mtk|currenttrack|cue|snapshot/i.test(k)).slice(0,60).map(k=>k+'='+String(st[k]).slice(0,40)), lastVuTail: out.vus[out.vus.length-1].slice(-70) };
}

