async (page) => {
  const start = await page.evaluate(() => window.__rx.length);
  await page.waitForTimeout(25000);
  return await page.evaluate((start) => {
    const state = {}; const vus = [];
    window.__rx.forEach((m, idx) => {
      for (const line of m.replace(/^3:::/, '').split('\n')) {
        const p = line.split('^');
        if ((p[0]==='SETD'||p[0]==='SETS') && p.length>=3) state[p[1]] = p.slice(2).join('^');
        if (p[0]==='VU2' && idx>=start) { const b = Uint8Array.from(atob(p[1]), c=>c.charCodeAt(0)); vus.push(Array.from(b)); }
      }
    });
    window.__state = state;
    const hdr = vus[0].slice(0,8), n = hdr[0], per = 6, off = 8;
    const avg=a=>Math.round(a.reduce((x,y)=>x+y,0)/a.length), max=a=>Math.max(...a);
    const rows = [];
    for (let c=0;c<n;c++){ const f=[[],[],[],[],[],[]];
      for (const v of vus) for (let k=0;k<6;k++) f[k].push(v[off+c*per+k]);
      rows.push([c+1,state[`i.${c}.name`],'mix',state[`i.${c}.mix`],'mute',state[`i.${c}.mute`],'gain',state[`i.${c}.gain`],'pan',state[`i.${c}.pan`],'b0',avg(f[0]),max(f[0]),'b1',avg(f[1]),max(f[1]),'b2',avg(f[2]),max(f[2]),'b3',avg(f[3]),'b4',avg(f[4]),'b5',f[5][f[5].length-1]].join(' '));
    }
    const keys = Object.keys(state);
    const last = vus[vus.length-1];
    return { hdr, frames: vus.length, len: vus[0].length, keyCount: keys.length, rows, masterKeys: keys.filter(k=>/^m\./.test(k)).slice(0,40).map(k=>k+'='+String(state[k]).slice(0,30)), ch12Keys: keys.filter(k=>k.startsWith('i.11.')&&!/\.eq\.|\.dyn\.|aux|fx/.test(k)).map(k=>k+'='+String(state[k]).slice(0,30)), hwKeys: keys.filter(k=>/^hw\.1[0-2]\./.test(k)).map(k=>k+'='+String(state[k]).slice(0,30)), tail: last.slice(off+n*per) };
  }, start);
}

