    return { frames: vus.length, rows, master:{ mix: state['m.mix'], L0p95:db(pct(L0,.95)),L1p95:db(pct(L1,.95)),L2p95:db(pct(L2,.95)),R0p95:db(pct(R0,.95)),R1p95:db(pct(R1,.95)) }, gate9: state['i.8.gate.thresh'], sub0: state['s.0.mix'] };
  }, start);
})(page);
