await (async (page) => {
  const mins = [8,20,30,40,50,60,70,80,90,100,110,120,132];
  const rows = [];
  const pct=(a,q)=>{const s=[...a].sort((x,y)=>x-y);return s[Math.floor((s.length-1)*q)]};
  const db = b => b===0 ? '.' : Math.round(b/3-80);
  for (const m of mins) {
    await page.mouse.click(Math.round(12+1771*(m*60)/8304), 190);
    await page.waitForTimeout(2000);
    const start = await page.evaluate(()=>window.__rx.length);
    await page.waitForTimeout(6000);
    const v = await page.evaluate((start)=>{const out=[];window.__rx.slice(start).forEach(m=>{for(const l of m.replace(/^3:::/,'').split('\n')){const p=l.split('^');if(p[0]==='VU2')out.push(Array.from(Uint8Array.from(atob(p[1]),c=>c.charCodeAt(0))));}});return out;},start);
    const ch = [];
    for (let c=0;c<18;c++) ch.push(db(pct(v.map(f=>f[8+c*6+2]),.95)));
    rows.push(`${m}m ` + ch.join(' ') + ` | out ${db(pct(v.map(f=>f[285]),.95))}`);
  }
  await page.mouse.click(1241, 190);
  await page.waitForTimeout(2000);
  await page.screenshot({ path: '.playwright-mcp/sweep-end.png', scale: 'css' });
  return { legend: 'postfader p95 dB: K1 K2 P3 P4 K5 DL DR DX DY SONG DANNY AUNTY DAVID UNCLE C4 C3 C1 C2', rows };
})(page);
