    const v = await page.evaluate((start)=>{const out=[];window.__rx.slice(start).forEach(m=>{for(const l of m.replace(/^3:::/,'').split('\n')){const p=l.split('^');if(p[0]==='VU2')out.push(Array.from(Uint8Array.from(atob(p[1]),c=>c.charCodeAt(0))));}});return out;},start);
    v.forEach(f=>all.push(f));
    const w=[]; for (let c=0;c<18;c++){ const a=v.filter(f=>f[8+c*6]>=66); w.push(a.length/v.length>0.15 ? Math.round(db(pct(a.map(f=>f[8+c*6+2]),.95))??-99) : '.'); }
    perWin.push(`${m}m `+w.join(' ')+` | out ${db(pct(v.map(f=>f[285]),.95))}`);
  }
  await page.mouse.click(1250, 190); await page.waitForTimeout(1500);
  await page.screenshot({ path: '.playwright-mcp/rejudge-1.png', scale: 'css' });
  const names=['KEY1','KEY2','PAD3','PAD4','KEY5','DRUML','DRUMR','DRUMX','DRUMY','SONG','DANNY','AUNTY','DAVID','UNCLE','CH4','CH3','CH1','CH2'];
  const rows=names.map((n,c)=>{ const a=all.filter(f=>f[8+c*6]>=66); return `${n}: active ${Math.round(a.length/all.length*100)}% | input p50 ${db(pct(a.map(f=>f[8+c*6]),.5))} p95 ${db(pct(a.map(f=>f[8+c*6]),.95))} max ${db(a.length?Math.max(...a.map(f=>f[8+c*6])):0)} | proc p95 ${db(pct(a.map(f=>f[8+c*6+1]),.95))} | postfader p50 ${db(pct(a.map(f=>f[8+c*6+2]),.5))} p95 ${db(pct(a.map(f=>f[8+c*6+2]),.95))} max ${db(a.length?Math.max(...a.map(f=>f[8+c*6+2])):0)}`; });
  return { frames: all.length, rows, legend:'active postfader p95 per window: K1 K2 P3 P4 K5 DL DR DX DY SONG DANNY AUNTY DAVID UNCLE C4 C3 C1 C2', perWin };
}

