{"rows":["110m aux3 0 -10 -11 0 maxPost 1 aux4 0 -10 -11 0 maxPost 1 over-3 77% | masterOut -20","115m aux3 0 -10 -12 -1 maxPost 1 aux4 0 -10 -12 0 maxPost 1 over-3 61% | masterOut -20","60m aux3 0 -10 -12 0 maxPost 1 aux4 0 -10 -10 0 maxPost 2 over-3 74% | masterOut -20"]}
### Ran Playwright code
```js
await (async (page) => {
  const pct=(a,q)=>{const s=[...a].sort((x,y)=>x-y);return s[Math.floor((s.length-1)*q)]};
  const db=b=>b===0?'.':Math.round(b/3-80);
  const rows=[];
  for(const m of [110,115,60]){
    await page.mouse.click(Math.round(12+1771*(m*60)/8304),190);await page.waitForTimeout(2000);
    const start=await page.evaluate(()=>window.__rx.length);await page.waitForTimeout(12000);
    const v=await page.evaluate((start)=>{const out=[];window.__rx.slice(start).forEach(m=>{for(const l of m.replace(/^3:::/,'').split('\n')){const p=l.split('^');if(p[0]==='VU2')out.push(Array.from(Uint8Array.from(atob(p[1]),c=>c.charCodeAt(0))));}});return out;},start);
    const b=o=>db(pct(v.map(f=>f[o]),.95));const mx=o=>db(Math.max(...v.map(f=>f[o])));
    rows.push(`${m}m aux3 ${[0,1,2,3].map(k=>b(244+k)).join(' ')} maxPost ${mx(247)} aux4 ${[0,1,2,3].map(k=>b(249+k)).join(' ')} maxPost ${mx(252)} over-3 ${Math.round(v.filter(f=>f[247]>=231).length/v.length*100)}% | masterOut ${b(285)}`);
  }
  await page.mouse.click(1475,190);await page.waitForTimeout(1200);
  await page.screenshot({ path: '.playwright-mcp/aux-2.png', scale: 'css' });
  return {rows};
})(page);
```

